import { Question, QuestionTypeId } from '../types/questions'
import { SubjectConfig, QuizFlowConfig } from '../types/quiz-flows'
import type { SubjectGroupId } from './subject-groups'

// 定義舊格式的型別（向後兼容）
export interface Subject {
  id: string
  name: string
  quizType: string
  quizOpen: boolean
  questionCount: number
  timeLimit: number
  lockTime?: string[]
  group?: SubjectGroupId // 所屬題組（見 data/subject-groups.ts）
  questions: Question[]
}

export type Subjects = Record<string, Subject>

/**
 * [function] convertToSubjectConfig
 * 將舊格式的 Subject 轉換為新格式的 SubjectConfig
 * @param {Subject} subject - 舊格式的 Subject
 * @returns {SubjectConfig} - 新格式的 SubjectConfig
 */
export function convertToSubjectConfig(subject: Subject): SubjectConfig {
  // 根據 quizType 決定 baseQuestionType
  let baseQuestionType: QuestionTypeId
  // 根據 quizType 決定 baseQuestionType
  switch (subject.quizType) {
    case 'once_choice':
      baseQuestionType = 'single_choice'
      break
    case 'multiple_choice':
      baseQuestionType = 'multiple_choice'
      break
    case 'true_false':
      baseQuestionType = 'true_false'
      break
    case 'vocabulary':
      baseQuestionType = 'vocabulary'
      break
    default:
      baseQuestionType = 'single_choice'
  }

  // 創建標準單階段流程配置
  const flowConfig: QuizFlowConfig = {
    id: `${subject.id}_flow`,
    name: subject.name,
    type: 'single_stage',
    stages: [
      {
        stageId: 'main',
        mode: 'standard',
        questionCount: subject.questionCount,
        timeLimit: subject.timeLimit,
      },
    ],
    totalTimeLimit: subject.timeLimit,
  }

  return {
    id: subject.id,
    name: subject.name,
    baseQuestionType,
    flowConfig,
    quizOpen: subject.quizOpen,
    lockTime: subject.lockTime,
    group: subject.group,
    questions: subject.questions,
  }
}

