//* 導出轉換後的 subjects（SubjectConfig 格式）
export const subjects: Record<string, SubjectConfig> = Object.fromEntries(
  Object.entries(rawSubjects).map(([key, subject]) => [
    key,
    convertToSubjectConfig(subject),
  ]),
)
